<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-title-hero"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'documents.eyebrow','Resources'))?></p><h1><?=View::escape(View::setting($siteContent??[],'documents.title','Documents'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'documents.introduction','Official public documents and downloads from FAST.'))?></p></div></section><section class="section"><div class="shell"><?php if($items===[]):?><div class="public-empty"><p><?=View::escape(View::setting($siteContent??[],'documents.empty','Published public documents will appear here.'))?></p></div><?php else:?><div class="department-card-grid"><?php foreach($items as$i):?><article class="department-card"><div><p class="eyebrow"><?=View::escape($i['type_name']??'Document')?><?=$i['version_label']?' · '.View::escape($i['version_label']):''?></p><h2><?=View::escape($i['title'])?></h2><p><?=View::escape($i['description']??'')?></p><a class="button button-secondary" href="<?=View::escape($baseUrl.ltrim(str_replace('public/','',$i['file_path']),'/'))?>" download>Download <?=View::escape($i['original_name'])?></a></div></article><?php endforeach;?></div><?php endif;?></div></section>
